// MinimockListPVZInspect logs each unmet expectation
func (m *PVZMock) MinimockListPVZInspect() {
	for _, e := range m.ListPVZMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PVZMock.ListPVZ at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterListPVZCounter := mm_atomic.LoadUint64(&m.afterListPVZCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ListPVZMock.defaultExpectation != nil && afterListPVZCounter < 1 {
		if m.ListPVZMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PVZMock.ListPVZ at\n%s", m.ListPVZMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PVZMock.ListPVZ at\n%s with params: %#v", m.ListPVZMock.defaultExpectation.expectationOrigins.origin, *m.ListPVZMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcListPVZ != nil && afterListPVZCounter < 1 {
		m.t.Errorf("Expected call to PVZMock.ListPVZ at\n%s", m.funcListPVZOrigin)
	}

	if !m.ListPVZMock.invocationsDone() && afterListPVZCounter > 0 {
		m.t.Errorf("Expected %d calls to PVZMock.ListPVZ at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ListPVZMock.expectedInvocations), m.ListPVZMock.expectedInvocationsOrigin, afterListPVZCounter)
	}
}

